from pathlib import Path
import json,csv
import numpy as np
E=Path(__file__).parent;R=E.parents[1];rows=json.loads((E/'results.json').read_text());assert len(rows)==18
old=list(csv.DictReader((E.parent/'kamp_v2_uq/analysis/metrics.csv').open()))
lines=['# 새 데이터 v2 어려운 후보 선택 학습 결과','','작성: 2026-10-02. 기본/MAL × 3 seed × 3 감독 목적 = 18 실행 완료. Train350·val66, test 미사용.','', '## 실험 설계','','기존 UQ를 출발점으로 박스와 특징을 고정하고 같은 62,007-parameter head를 15 epoch 추가 학습했다. 기존 quality 목적만 계속 학습한 대조군과 hard-pair/listwise 목적을 비교하여 추가 학습 자체의 효과를 분리한다. 세 목적의 head 초기값·학습순서·epoch·optimizer가 같다. 마지막 epoch만 평가하며 validation으로 설정을 고르지 않았다.','', 'Hard-pair는 같은 GT에 대응하고 두 IoU≥.5, 차이≥.05인 후보 쌍의 우열을 학습한다. Listwise는 예측 박스 IoU≥.7의 greedy 클러스터에서 softmax(IoU/.1)를 목표로 순위를 학습한다. 클러스터는 GT 없이 생성되며 GT는 train 감독에만 쓰인다. 품질 loss에 각 보조 loss의 .1배를 더한다.','', '추론은 기존과 같은 단일 후보별 quality head와 sqrt(base score×quality)다. 따라서 이는 새로운 관계망 아키텍처가 아니라 학습 목적의 통제 실험이다. 모든 bbox는 저장된 동일 좌표다.','', '## 공통 평가','','원본 좌표 COCO 평가, NMS .7, scale1.0. 기존 base score≥.001 고정 후보 집합을 사용한다. 앞선 UQ 실험에서는 이 support 제한의 AP 영향이 없음을 확인했다. 아래는 세 seed 평균이며 정밀 대표는 GT에 인접한 후보 중 최고점수 후보의 IoU≥.75 개수다. 이 대표 지표는 사후 진단이며 GT를 추론에 사용하지 않는다.','','| 부모 | 추가 학습 | AP | AP75 | TP, FP≤6 | 정밀 대표 |','|---|---|---:|---:|---:|---:|']
for base in ['base','mal']:
 oo=[r for r in old if r['variant']==f'dfine_{base}_UQ' and r['setting']=='nms07'];mean=lambda rr,k:np.mean([float(r[k]) for r in rr])
 lines.append(f"| {base} | 이전 UQ | {mean(oo,'AP'):.2f} | {mean(oo,'AP75'):.2f} | {mean(oo,'TP_FP6'):.2f} | — |")
 for mode in ['quality','hard_pair','listwise']:
  rr=[r for r in rows if r['base']==base and r['mode']==mode];lines.append(f"| {base} | {mode} | {mean(rr,'AP'):.2f} | {mean(rr,'AP75'):.2f} | {mean(rr,'TP_FP6'):.2f} | {mean(rr,'new_precise'):.2f} |")
lines+=['','## 추가 학습 대조군 대비 seed별 차이','','| 부모 | 목적 | seed | ΔAP | ΔAP75 | ΔTP(FP≤6) | Δ정밀 대표 |','|---|---|---|---:|---:|---:|---:|']
paired=[]
for r in rows:
 if r['mode']=='quality':continue
 c=next(x for x in rows if x['base']==r['base'] and x['seed']==r['seed'] and x['mode']=='quality');d={k:r[k]-c[k] for k in ['AP','AP75','TP_FP6','new_precise']};paired.append(dict(base=r['base'],seed=r['seed'],mode=r['mode'],**d));lines.append(f"| {r['base']} | {r['mode']} | {r['seed']} | {d['AP']:+.2f} | {d['AP75']:+.2f} | {d['TP_FP6']:+} | {d['new_precise']:+} |")
lines+=['','## 검증과 해석 범위','','- 초기 head 출력과 기존 UQ 출력 일치를 확인했다. 모든 학습 step에서 loss/gradient가 유한했다. detector는 호출하거나 수정하지 않고 앞선 검증된 특징·좌표 cache만 사용했다.','- 18개 실행 모두 15 epoch를 완료했다. 각 목적의 head parameter 수 및 초기 상태가 같다.','- GT는 train target과 사후 지표에만 사용했다. 실제 점수·NMS는 GT를 읽지 않는다.','- 세 seed는 같은 데이터 분할이며, validation은 이미 checkpoint 선택과 반복 분석에 사용됐다. 독립 최종 성능이나 통계적 유의성을 주장하지 않는다.','- 이번에 고정한 보조 loss .1은 목적 간 gradient scale을 맞춘 값이 아니다. 따라서 결과는 이 구현·계수에 대한 증거이며 모든 pair/listwise 방식에 대한 반증은 아니다.','- FP≤6은 validation 객체 수준 운영점이며 정상 제품 자동 통과 안전율이 아니다.','', '## 자료','','- [실행 설정](experiments/kamp_v2_hard_selection/README.md)','- [전체 수치](experiments/kamp_v2_hard_selection/results.json)','- [학습 로그](experiments/kamp_v2_hard_selection/run.log)','- [완료 기록](experiments/kamp_v2_hard_selection/completion.json)']
(R/'새_데이터_v2_어려운_후보선택_학습결과.md').write_text('\n'.join(lines)+'\n');(E/'paired.json').write_text(json.dumps(paired,indent=2));print('\n'.join(lines))
qd=json.loads((E/'quality_diagnostic.json').read_text())
extra=['## 품질 점수 단독 진단','','기존 object score와 결합하지 않은 quality 순위도 사후 진단했다. 이는 inference 설정을 바꿔 채택한 실험이 아니다. Hard-pair 정확도는 예측 클러스터 내부·같은 GT·두 IoU≥.5·IoU 차이≥.05인 최대64쌍/이미지에 대한 이미지 평균이다. 앞선 probe의 GT별 전체 후보 쌍 정확도와 직접 비교하면 안 된다.','','| 부모 | 목적 | hard-pair 정확도 | quality 단독 정밀 대표 |','|---|---|---:|---:|']
for b in ['base','mal']:
 for m in ['quality','hard_pair','listwise']:
  rr=[r for r in qd if r['base']==b and r['mode']==m];extra.append(f"| {b} | {m} | {np.mean([r['hard_pair_accuracy'] for r in rr])*100:.1f}% | {np.mean([r['quality_only_precise'] for r in rr]):.2f} |")
extra+=['','MAL에서 hard-pair 정확도는 63.6→64.5%로 소폭 상승했으나, quality 단독 정밀 대표는 53.0개로 기존 UQ 결합 점수의 53.33개보다 높지 않았다. Listwise의 quality 단독은 48.0개였다. 따라서 “좋은 quality를 object score가 가린다”만으로 이번 실패를 설명할 수 없다. 품질 추정 자체의 정밀 대표 구별력도 충분하지 않았다.','', '## 결론과 다음 방향','','**이번 조건에서는 hard-pair/listwise 추가 학습을 채택하지 않는다. 기존 MAL+UQ+NMS .7+scale1.0을 유지한다.** MAL의 AP는 이전39.38 대비 hard-pair39.31, listwise39.38로 뚜렷한 개선이 없고, 정밀 대표53.33개와 TP141.67개도 그대로였다. 같은 epoch를 더 학습한 quality 대조군과 비교해도 이득은 작고 seed별 일관성이 없다.','', '스토리는 “점수 보정은 AP에 도움을 줬지만, 동일 이물의 정밀 대표 선택까지 해결하지는 못했다. 상대 순위 감독을 강화해도 이 문제가 해소되지 않아, 현재 query 요약 특징만으로 경계 차이를 판별하는 접근의 실용적 근거가 약해졌다”가 적절하다. 정보 부재나 라벨 오류를 확정하는 결론은 아니다.','', '다음은 더 큰 query relation 구조를 바로 학습하기보다, **박스 주변의 로컬 영상·고해상도 특징이 추가 정보를 제공하는지**를 작은 진단으로 확인하는 방향이 낫다. 동일 부모·고정 후보에서 query-only 대조군과 query+로컬 특징을 비교하고, 대표 IoU/AP75/낮은-FP TP의 동시 개선을 확인해야 한다. 로컬 특징 추출은 predicted bbox를 사용해야 하며 GT는 학습 감독에만 사용한다. 이전 BR/BPS를 그대로 재실행하거나 P2 전체 경로를 다시 붙이는 것과 구분한다.','', '이마저 개선되지 않으면 모듈 추가를 멈추고, 남은 M3 실패·GT 경계 불확실성·재검사 조건 분석에 집중한다. 정상 제품이 없는 현재 자료에서 자동 통과 안전성을 확정할 수는 없다.','', '이번 작업은 학습·평가 전체 약85초로 완료돼 예약 실행을 만들지 않았다. 새 detector 학습 또는 후속 모듈 학습은 실행하지 않았다.']
p=R/'새_데이터_v2_어려운_후보선택_학습결과.md';s=p.read_text();s=s.replace('## 실험 설계','**결론: 어려운 후보에 집중한 감독도 정밀 대표 선택·낮은 FP 검출 수를 개선하지 못했다. 이번 변경은 채택하지 않고 기존 MAL+UQ를 유지한다.**\n\n## 실험 설계');p.write_text(s+'\n'+'\n'.join(extra)+'\n')
